@app.cell(hide_code=True)
def _(COLS, RU2COL, cards, dep_pair_ph, dep_q_ph, dep_view, mo, white):
    _a, _b = dep_pair_ph.value.split(" и ")
    _ca, _cb = RU2COL[_a], RU2COL[_b]
    _img, _rho, _chi2, _p, _v, _dof = dep_view(white[_ca].to_numpy(float), white[_cb].to_numpy(float), dep_q_ph.value,
                                              f"{_a}, {COLS[_ca][1]}", f"{_b}, {COLS[_cb][1]}")
    mo.vstack([cards([("ρ Спирмена", f"{_rho:+.2f}", "сила и направление"), ("χ²", f"{_chi2:.0f}", f"df = {_dof}"),
                      ("p", f"{_p:.1e}", "< 0.05 — связь есть"), ("V Крамера", f"{_v:.2f}", "0 — нет связи, 1 — полная")]), _img])
    return


