@app.cell(hide_code=True)
def _(code_block, fig, mo, out_text, section, table_html):
    section(
        mo.md("<a id=\"rv01-norm\"></a>\n### 2.4 Normalization"),
        out_text("после z: среднее -1.20e-15, СКО 1.000\nдоля |z| ≤ 1, 2, 3: [np.float64(0.694), np.float64(0.9573), np.float64(0.9935)] у N(0,1): [0.6827, 0.9545, 0.9973]"),
        fig("w008_24.png"),
        mo.md("<a id=\"fig6\"></a>\n*Рис. 6. pH: распределение после преобразования в сравнении с плотностью $N(0, 1)$.*"),
        mo.md("**Результаты:**\n\n- После z-преобразования: среднее 0 (до $10^{-15}$), СКО 1.000, асимметрия и эксцесс те же (0.46 и 0.53). Это стандартизация.\n- Доли $|z| \\le 1, 2, 3$: 0.694, 0.957, 0.9935; у $N(0, 1)$: 0.683, 0.954, 0.9973.\n- Min-max, затем z: та же гистограмма, что после z.\n\n**Зачем и как.** Стандартизация $z = (x - \\bar x)/s$ переводит pH в число стандартных отклонений от среднего: у новой величины среднее 0 и СКО 1. Это линейное преобразование, оно только сдвигает шкалу и меняет её масштаб, поэтому форма распределения не меняется, асимметрия и эксцесс остаются прежними. Нужно это, чтобы сравнивать величины в разных единицах на одной шкале и пользоваться таблицами $N(0, 1)$; на том же переходе через $Z \\sim N(0,1)$ построен датчик во втором спринте. Но pH не нормален (раздел 2.6), поэтому $z$ совпадает с $N(0, 1)$ только приближённо: это видно по долям $|z| \\le 3$ (0.9935 против 0.9973)."),
        code_block("z_ph = normalize.zscore(x_rv01)\npairs = {\"pH: z = (x − x̄)/s\": z_ph, \"pH: min-max, затем z\": normalize.zscore(normalize.minmax(x_rv01))}\nplots.normalization_panel(pairs, \"rv01_normalization.png\")\nprint(f\"после z: среднее {z_ph.mean():.2e}, СКО {z_ph.std(ddof=1):.3f}\")\nprint(\"доля |z| ≤ 1, 2, 3:\", [round(np.mean(np.abs(z_ph) <= k), 4) for k in (1, 2, 3)], \"у N(0,1): [0.6827, 0.9545, 0.9973]\")"),
    )
    return


