@app.cell(hide_code=True)
def _(code_block, fig, mo, out_text, section, table_html):
    section(
        mo.md("<a id=\"rv02-hyp\"></a>\n### 3.6 Hypotheses\n\nУровень значимости $\\alpha = 0.05$ для каждой проверки; поправка на множественность в [Lab resume](#resume)."),
        table_html("<div>\n<style scoped>\n    .dataframe tbody tr th:only-of-type {\n        vertical-align: middle;\n    }\n\n    .dataframe tbody tr th {\n        vertical-align: top;\n    }\n\n    .dataframe thead th {\n        text-align: right;\n    }\n</style>\n<table border=\"1\" class=\"dataframe\">\n  <thead>\n    <tr style=\"text-align: right;\">\n      <th></th>\n      <th>данные</th>\n      <th>test</th>\n      <th>H0</th>\n      <th>p</th>\n      <th>решение</th>\n    </tr>\n  </thead>\n  <tbody>\n    <tr>\n      <th>0</th>\n      <td>ln X, все 4898</td>\n      <td>D'Agostino K²</td>\n      <td>ln X ~ нормальное</td>\n      <td>1.8880e-21</td>\n      <td>отвергаем H0</td>\n    </tr>\n    <tr>\n      <th>1</th>\n      <td>ln X, все 4898</td>\n      <td>χ² Пирсона, 20 интервалов</td>\n      <td>ln X ~ нормальное</td>\n      <td>1.2739e-08</td>\n      <td>отвергаем H0</td>\n    </tr>\n    <tr>\n      <th>2</th>\n      <td>X, все 4898</td>\n      <td>χ² Пирсона, 17 интервалов, df 13</td>\n      <td>X ~ логнормальное со сдвигом</td>\n      <td>3.0871e-06</td>\n      <td>отвергаем H0</td>\n    </tr>\n    <tr>\n      <th>3</th>\n      <td>ln X, выборка 200</td>\n      <td>D'Agostino K²</td>\n      <td>ln X ~ нормальное</td>\n      <td>4.4889e-01</td>\n      <td>нет оснований отвергнуть H0</td>\n    </tr>\n    <tr>\n      <th>4</th>\n      <td>X, все 4898</td>\n      <td>D'Agostino K²</td>\n      <td>X ~ нормальное</td>\n      <td>5.1923e-118</td>\n      <td>отвергаем H0</td>\n    </tr>\n  </tbody>\n</table>\n</div>"),
        mo.md("**Результаты:**\n\n- **H3 ($\\ln X$ нормален, логнормальное без сдвига):** $K^2$ $p \\approx 10^{-21}$, $\\chi^2$ $p \\approx 10^{-8}$ на всех 4898. $H_0$ отвергается. На выборке 200: $K^2$ $p = 0.45$.\n- **H3b (логнормальное со сдвигом):** $\\chi^2$ (17 интервалов, $\\mathrm{df} = 13$) $p \\approx 3\\cdot 10^{-6}$. $H_0$ отвергается.\n- Для сравнения: X нормален, $K^2$ $p \\approx 10^{-118}$. Статистика $K^2$ 540 для X и 95 для $\\ln X$."),
        code_block("# H3: ln(кислотности) распределён нормально (кислотность логнормальна без сдвига)\n# H3b: кислотность ~ логнормальное со сдвигом (3 параметра)\nlx = np.log(x_rv02)\nsub = sampling.draw(x_rv02, 200, replace=False, seed=SEED)\nchi_ln_rv02 = dist.chi2_gof(lx, \"norm\", step=0)        # после логарифма сетка неравномерная, step=0\nchi_ln3_rv02 = dist.chi2_gof(x_rv02, \"lognorm\")        # шаг 0.1 определяется по данным\nrows = [\n    hyp.normality_dagostino(lx) | {\"H0\": \"ln X ~ нормальное\", \"данные\": \"ln X, все 4898\"},\n    chi_ln_rv02 | {\"test\": f\"χ² Пирсона, {chi_ln_rv02['bins']} интервалов\", \"H0\": \"ln X ~ нормальное\", \"данные\": \"ln X, все 4898\"},\n    chi_ln3_rv02 | {\"test\": f\"χ² Пирсона, {chi_ln3_rv02['bins']} интервалов, df {chi_ln3_rv02['dof']}\", \"H0\": \"X ~ логнормальное со сдвигом\", \"данные\": \"X, все 4898\"},\n    hyp.normality_dagostino(np.log(sub)) | {\"H0\": \"ln X ~ нормальное\", \"данные\": \"ln X, выборка 200\"},\n    hyp.normality_dagostino(x_rv02) | {\"H0\": \"X ~ нормальное\", \"данные\": \"X, все 4898\"},\n]\nh_rv02 = pd.DataFrame(rows)[[\"данные\", \"test\", \"H0\", \"p\"]]\nh_rv02[\"решение\"] = np.where(h_rv02.p < 0.05, \"отвергаем H0\", \"нет оснований отвергнуть H0\")\nh_rv02"),
    )
    return


