def _(COLS, df_html, fit_bins_alc, fit_fams_alc, fit_view, mo, white):
    _label, _unit, _step = COLS["alcohol"]
    _img, _tab = fit_view(white["alcohol"].to_numpy(float), fit_fams_alc.value, fit_bins_alc.value, _step, _label, _unit, "alc")
