        code_block("# H4: спирт распределён по гамма-закону со сдвигом\nh4 = dist.chi2_gof(x_rv03, \"gamma\")\nh4 |= {\"test\": f\"χ² Пирсона, {h4['bins']} интервалов, df {h4['dof']}\", \"H0\": \"X ~ гамма со сдвигом\"}\n# H5: в хороших винах (качество ≥ 7) спирт не больше, чем в остальных: H0 P(A > B) ≤ 1/2\ngood, rest = white.alcohol[white.quality >= 7], white.alcohol[white.quality < 7]\nh5 = hyp.mann_whitney(good, rest, alternative=\"greater\")\nh_rv03 = pd.DataFrame([h4, h5])[[\"test\", \"H0\", \"p\", \"decision\"]]\ndisplay(h_rv03)\nprint(f\"Хороших вин {len(good)}, остальных {len(rest)}; средний спирт {good.mean():.2f} против {rest.mean():.2f} % об.\")\nprint(f\"Оценка P(спирт у хорошего > спирт у остального) = {h5['p_a_gt_b']:.3f}\")\nplots.two_groups(good.to_numpy(), rest.to_numpy(), \"качество ≥ 7\", \"качество < 7\", \"спирт, % об.\",\n                 \"Спирт и оценка качества\", \"rv03_quality.png\");"),
